public class RecordSearchService with sharing {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            // --- Validate maxRows ---
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200');
            }

            // --- Validate and resolve object (case-insensitive) ---
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API name is required');
            }
            Schema.SObjectType objType = Schema.getGlobalDescribe().get(objectApiName);
            if (objType == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }
            Schema.DescribeSObjectResult objDescribe = objType.getDescribe();

            if (!objDescribe.isAccessible()) {
                throw new SearchException(
                    'User does not have read access to object: ' + objDescribe.getName()
                );
            }

            // --- Build a case-insensitive field lookup map ---
            Map<String, Schema.SObjectField> fieldMap = new Map<String, Schema.SObjectField>();
            Map<String, Schema.SObjectField> rawFields = objDescribe.fields.getMap();
            for (String key : rawFields.keySet()) {
                fieldMap.put(key.toLowerCase(), rawFields.get(key));
            }

            // --- Validate fields list ---
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('Fields list must not be null or empty');
            }

            // --- Build SELECT clause (Id always included) ---
            Set<String> selectFields = new Set<String>{ 'Id' };

            for (String f : fields) {
                if (String.isBlank(f)) {
                    throw new SearchException('Field name in fields list cannot be blank');
                }
                Schema.SObjectField sf = fieldMap.get(f.trim().toLowerCase());
                if (sf == null) {
                    throw new SearchException(
                        'Field not found on ' + objDescribe.getName() + ': ' + f
                    );
                }
                if (!sf.getDescribe().isAccessible()) {
                    throw new SearchException(
                        'User does not have read access to field: ' + sf.getDescribe().getName()
                    );
                }
                selectFields.add(sf.getDescribe().getName());
            }

            // --- Build WHERE clause ---
            List<String> whereClauses = new List<String>();
            if (filters != null) {
                for (String filterKey : filters.keySet()) {
                    Object filterValue = filters.get(filterKey);

                    if (String.isBlank(filterKey)) {
                        throw new SearchException('Filter field name cannot be blank');
                    }

                    Schema.SObjectField sf = fieldMap.get(filterKey.trim().toLowerCase());
                    if (sf == null) {
                        throw new SearchException(
                            'Filter field not found on ' + objDescribe.getName()
                            + ': ' + filterKey
                        );
                    }
                    if (!sf.getDescribe().isAccessible()) {
                        throw new SearchException(
                            'User does not have read access to filter field: '
                            + sf.getDescribe().getName()
                        );
                    }

                    whereClauses.add(
                        sf.getDescribe().getName() + ' = ' + formatSoqlValue(filterValue)
                    );
                }
            }

            // --- Build ORDER BY clause ---
            String orderByClause = '';
            if (!String.isBlank(orderByField)) {
                Schema.SObjectField sf = fieldMap.get(orderByField.trim().toLowerCase());
                if (sf == null) {
                    throw new SearchException(
                        'Order-by field not found on ' + objDescribe.getName()
                        + ': ' + orderByField
                    );
                }
                if (!sf.getDescribe().isAccessible()) {
                    throw new SearchException(
                        'User does not have read access to order-by field: '
                        + sf.getDescribe().getName()
                    );
                }
                orderByClause = ' ORDER BY ' + sf.getDescribe().getName() + ' ASC';
            }

            // --- Assemble and execute dynamic SOQL ---
            String soql =
                'SELECT ' + String.join(new List<String>(selectFields), ', ')
                + ' FROM ' + objDescribe.getName();

            if (!whereClauses.isEmpty()) {
                soql += ' WHERE ' + String.join(whereClauses, ' AND ');
            }
            soql += orderByClause;
            soql += ' LIMIT ' + maxRows;

            return Database.query(soql);

        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException('Search failed: ' + e.getMessage());
        }
    }

    /**
     * Converts an arbitrary filter value into a SOQL-safe literal.
     * String values are single-quoted and escaped; all other types are
     * rendered as their SOQL-compatible unquoted representation.
     */
    private static String formatSoqlValue(Object value) {
        if (value == null) {
            return 'null';
        }
        if (value instanceof String) {
            return "'" + String.escapeSingleQuotes((String) value) + "'";
        }
        if (value instanceof Boolean) {
            return (Boolean) value ? 'true' : 'false';
        }
        if (value instanceof DateTime) {
            return ((DateTime) value).formatGmt('yyyy-MM-dd''T''HH:mm:ss''Z''');
        }
        if (value instanceof Date) {
            Date d = (Date) value;
            return pad4(d.year()) + '-' + pad2(d.month()) + '-' + pad2(d.day());
        }
        // Id, Integer, Decimal, and any other type are safe as-is
        return String.valueOf(value);
    }

    private static String pad2(Integer n) {
        String s = String.valueOf(n);
        return s.length() < 2 ? '0' + s : s;
    }

    private static String pad4(Integer n) {
        String s = String.valueOf(n);
        while (s.length() < 4) {
            s = '0' + s;
        }
        return s;
    }
}
