    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        // Case-insensitive object lookup via Schema
        Map<String, Schema.SObjectType> globalMap = Schema.getGlobalDescribe();
        Schema.SObjectType sObjectType = null;
        for (String key : globalMap.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                sObjectType = globalMap.get(key);
                break;
            }
        }

        if (sObjectType == null) {
            throw new PicklistServiceException('Object not found: ' + objectApiName);
        }

        // Case-insensitive field lookup via Describe
        Schema.DescribeSObjectResult describe = sObjectType.getDescribe();
        Map<String, Schema.SObjectField> fieldMap = describe.getFieldMap();
        Schema.SObjectField sObjectField = null;
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                sObjectField = fieldMap.get(key);
                break;
            }
        }

        if (sObjectField == null) {
            throw new PicklistServiceException('Field not found on ' + objectApiName + ': ' + fieldApiName);
        }

        // Validate field type
        Schema.DescribeFieldResult fieldDesc = sObjectField.getDescribe();
        if (fieldDesc.getType() != Schema.DisplayType.PickList
            && fieldDesc.getType() != Schema.DisplayType.MultiPickList) {
            throw new PicklistServiceException(
                'Field ' + fieldApiName + ' on ' + objectApiName
                + ' is not a picklist or multi-select picklist.');
        }

        // Get active picklist values in defined order via SOQL
        List<EntityDefinition> objDefs = [
            SELECT Id FROM EntityDefinition
            WHERE Upper(DeveloperName) = :objectApiName.toUpperCase()
            LIMIT 1
        ];

        List<EntityFieldDefinition> fieldDefs = [
            SELECT Id FROM EntityFieldDefinition
            WHERE EntityDefinitionId = :objDefs[0].Id
            AND Upper(DeveloperName) = :fieldApiName.toUpperCase()
            LIMIT 1
        ];

        List<PicklistValueInfo> picklistValues = [
            SELECT Label, Value, IsDefaultValue, SortOrder
            FROM PicklistValueInfo
            WHERE PicklistFieldAndValue.PicklistFieldId = :fieldDefs[0].Id
            AND IsActive = true
            ORDER BY SortOrder
        ];

        List<Option> result = new List<Option>();
        for (PicklistValueInfo pvi : picklistValues) {
            Option opt = new Option();
            opt.value = pvi.Value;
            opt.label = pvi.Label;
            opt.isDefault = pvi.IsDefaultValue;
            result.add(opt);
        }

        return result;
    }
}
