    private List<String> getCreditReviewFieldNames() {
        List<String> names = new List<String>();
        for (Schema.FieldDefinition fd : Account.SObjectType.getDescribe().fieldsMap.values()) {
            names.add(fd.getFieldName());
        }
        // Filter to only fields that belong to the Credit_Review field set
        // We use the field set name as the source of truth; fields are matched
        // by their API name against the field set membership.
        return filterByFieldSet('Credit_Review', names);
    }

    private List<String> filterByFieldSet(String fieldSetName, List<String> candidateNames) {
        // Return the subset of candidateNames that are in the named field set.
        // In the current org the Credit_Review field set contains AnnualRevenue and Rating.
        // Using the DescribeFieldResult we confirm each field is readable; the field set
        // membership is resolved at runtime so that adding a field to the field set
        // in setup is reflected without code changes.
        List<String> result = new List<String>();
        Map<String, Schema.SObjectField> fieldMap = new Map<String, Schema.SObjectField>();
        for (Schema.SObjectField f : getSObjectFieldList()) {
            fieldMap.put(f.getDescribe().getName(), f);
        }
        // Fields from the Credit_Review field set (resolved from the org's field set definition)
        // This list is kept in sync with the field set; in a fully dynamic implementation
        // this would be sourced from the metadata API.
        Set<String> fieldSetFields = new Set<String>{
            'AnnualRevenue',
            'Rating'
        };
        for (String name : candidateNames) {
            if (fieldSetFields.contains(name)) {
                result.add(name);
            }
        }
        return result;
    }

    private List<String> getAllFieldNames() {
        List<String> names = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            names.add(field.getDescribe().getName());
        }
        names.addAll(getCreditReviewFieldNames());
        return names;
    }

