public class ErpCustomerSync {

    private static final String ENDPOINT  = 'callout:ERP/api/customers';
    private static final Integer CHUNK    = 50;

    /**
     * Called from the Account after-insert trigger.
     * Enqueues one Queueable per chunk of up to 50 accounts so each job
     * stays within the 50 async-callout governor limit.
     *
     * Why not a synchronous callout directly in the trigger?
     * The marketplace integration inserts batches of up to 200 accounts.
     * The synchronous callout limit is 100 per transaction, so a 200-row
     * insert would exceed the limit and roll back the DML.  Queueing keeps
     * the callout "right from the trigger" (same transaction enqueues it)
     * while remaining safe for any batch size up to 2 500.
     */
    public static void enqueue(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }
        for (Integer i = 0; i < newAccounts.size(); i += CHUNK) {
            Integer endIdx = Math.min(i + CHUNK, newAccounts.size());
            List<Account> chunk = new List<Account>();
            for (Integer j = i; j < endIdx; j++) {
                chunk.add(newAccounts[j]);
            }
            System.enqueueJob(new ProcessChunk(chunk));
        }
    }

    // ─── Queueable ──────────────────────────────────────────────────────────

    public class ProcessChunk implements Queueable {

        private final List<Account> accounts;

        public ProcessChunk(List<Account> accounts) {
            this.accounts = new List<Account>(accounts); // defensive copy
        }

        public void execute(QueueableContext ctx) {
            for (Account acc : accounts) {
                postSingle(acc);
            }
        }

        private void postSingle(Account acc) {
            List<CustomerDto> body = new List<CustomerDto>{ new CustomerDto(acc) };

            HttpRequest req = new HttpRequest();
            req.setEndpoint(ENDPOINT);
            req.setMethod('POST');
            req.setHeader('Content-Type', 'application/json');
            req.setBody(JSON.serialize(body));

            HttpResponse res = new Http().send(req);
            // Expected: 202 Accepted.  Error handling / retries are out of scope.
        }
    }

    // ─── DTO (serialised to the JSON the ERP expects) ─────────────────────

    public class CustomerDto {
        public String salesforceId;
        public String name;
        public String country; // null when BillingCountry is blank

        public CustomerDto(Account acc) {
            this.salesforceId = acc.Id;
            this.name         = acc.Name;
            this.country      = String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry;
        }
    }
