public class CaseSurveyJob implements Queueable {

    private final Id singleCaseId;
    private final List<Id> batchCaseIds;

    /**
     * Single-case mode: processes one case by creating its CSAT survey Task.
     */
    public CaseSurveyJob(Id caseId) {
        this.singleCaseId = caseId;
    }

    /**
     * Chainer mode: carries a list of remaining Case IDs to fan out
     * into individual CaseSurveyJob instances.
     */
    private CaseSurveyJob(List<Id> caseIds) {
        this.batchCaseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        if (batchCaseIds != null) {
            // Chainer mode: fan out the remaining IDs
            enqueueBatch(batchCaseIds);
            return;
        }
        // Single-case mode: create the survey Task
        processSingleCase(singleCaseId);
    }

    /**
     * Static helper: enqueues one CaseSurveyJob per Id, respecting the
     * 50-queueable-jobs-per-transaction limit.
     *
     * - If the list has 50 or fewer IDs, enqueue them all directly.
     * - Otherwise, enqueue 49 direct jobs plus 1 chainer that carries
     *   the rest (total = 50, within the limit).
     */
    public static void enqueueBatch(List<Id> caseIds) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        if (caseIds.size() <= 50) {
            for (Id id : caseIds) {
                System.enqueueJob(new CaseSurveyJob(id));
            }
        } else {
            List<Id> firstBatch = caseIds.subList(0, 49);
            List<Id> remaining  = caseIds.subList(49, caseIds.size());

            for (Id id : firstBatch) {
                System.enqueueJob(new CaseSurveyJob(id));
            }
            // 49 + 1 chainer = 50 enqueued (within limit)
            System.enqueueJob(new CaseSurveyJob(remaining));
        }
    }

    private void processSingleCase(Id caseId) {
        Case c = [SELECT Id, CaseNumber, ContactId
                       FROM Case WHERE Id = :caseId];

        if (c.ContactId == null) {
            return;
        }

        insert new Task(
            WhatId       = c.Id,
            WhoId        = c.ContactId,
            Subject      = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status       = 'Not Started'
        );
    }
}
