```apex
public class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Integer sentCount = 0;
        Integer batchSize = 10; // governor limit: 10 single emails per transaction

        for (Integer i = 0; i < opportunityIds.size(); i += batchSize) {
            Integer end = Math.min(i + batchSize, opportunityIds.size());
            List<Id> chunk = opportunityIds.sublist(i, end);

            if (i == 0) {
                // First chunk: process synchronously in this transaction
                sentCount += sendChunk(chunk);
            } else {
                // Remaining chunks: each Queueable gets its own transaction
                System.enqueueJob(new RenewalChunkQueueable(chunk));
            }
        }

        return sentCount;
    }

    private static Integer sendChunk(List<Id> opportunityIds) {
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Name, CloseDate, OwnerId FROM Opportunity WHERE Id IN :opportunityIds]
        );

        Integer sentCount = 0;
        for (Id oppId : opportunityIds) {
            Opportunity opp = oppMap.get(oppId);
            if (opp == null || opp.OwnerId == null) {
                continue;
            }

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);
            email.setPlainTextBody(
                'Hello,\n\n' +
                'The opportunity "' + opp.Name + '" has a close date of ' +
                opp.CloseDate +
                ' and is due for renewal. Please follow up with the customer.\n\n' +
                'Regards'
            );

            Messaging.SendEmailResult[] results = Messaging.sendEmail(
                new Messaging.SingleEmailMessage[] { email }
            );

            if (results != null && !results.isEmpty() && results[0].success) {
                sentCount++;
            }
        }

        return sentCount;
    }

    private class RenewalChunkQueueable implements Queueable {
        private List<Id> chunk;

        public RenewalChunkQueueable(List<Id> chunk) {
            this.chunk = chunk;
        }

        public void execute(QueueableContext ctx) {
            sendChunk(chunk);
        }
    }
}
