public class AccountCountrySync {

    public static void handle() {
        List<Account> newAccounts = (List<Account>) Trigger.new;
        List<Account> oldAccounts = (List<Account>) Trigger.old;

        Map<Id, Account> oldMap = new Map<Id, Account>(oldAccounts);
        Set<Id> changedAccountIds = new Set<Id>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldMap.get(acc.Id);
            if (oldAcc != null && acc.BillingCountry != oldAcc.BillingCountry) {
                changedAccountIds.add(acc.Id);
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        Map<Id, List<Contact>> contactsByAccount = new Map<Id, List<Contact>>();
        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            if (!contactsByAccount.containsKey(c.AccountId)) {
                contactsByAccount.put(c.AccountId, new List<Contact>());
            }
            contactsByAccount.get(c.AccountId).add(c);
        }

        List<Contact> toUpdate = new List<Contact>();

        for (Account acc : newAccounts) {
            if (!changedAccountIds.contains(acc.Id)) {
                continue;
            }

            String oldCountry = oldMap.get(acc.Id).BillingCountry;
            String newCountry = acc.BillingCountry;
            List<Contact> accContacts = contactsByAccount.get(acc.Id);

            if (accContacts == null) {
                continue;
            }

            for (Contact c : accContacts) {
                if (String.isBlank(c.MailingCountry) || c.MailingCountry == oldCountry) {
                    c.MailingCountry = newCountry;
                    toUpdate.add(c);
                }
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
```

