public class EmployerService {

    /**
     * Sets the current employer for a set of contacts using NPSP's affiliation model.
     *
     * For each contact/employer pair:
     *   - Creates a Current affiliation if one does not already exist.
     *   - Updates the Contact's npsp__Primary_Affiliation__c so NPSP's standard
     *     mechanism promotes the new affiliation to Primary/Current and demotes
     *     the previous one to Former with EndDate = today.
     *   - Skips any pair where the target org is already the contact's primary
     *     affiliation (no duplicate created, no unnecessary update).
     *
     * Uses at most 1 SOQL query and 2 DML statements regardless of map size.
     *
     * @param employerByContactId  Keys = Contact Id, Values = Organization Account Id
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // Query 1: fetch every affiliation for the contacts in scope
        Map<Id, List<npe5__Affiliation__c>> affsByContact =
            new Map<Id, List<npe5__Affiliation__c>>();

        for (npe5__Affiliation__c aff : [
            SELECT npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Status__c,
                   npe5__Primary__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
        ]) {
            if (!affsByContact.containsKey(aff.npe5__Contact__c)) {
                affsByContact.put(aff.npe5__Contact__c, new List<npe5__Affiliation__c>());
            }
            affsByContact.get(aff.npe5__Contact__c).add(aff);
        }

        // Determine work to do
        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);

            List<npe5__Affiliation__c> existingAffs = affsByContact.get(contactId);
            if (existingAffs == null) {
                existingAffs = new List<npe5__Affiliation__c>();
            }

            // Find the affiliation (if any) linking this contact to the target org
            npe5__Affiliation__c targetAff = null;
            for (npe5__Affiliation__c aff : existingAffs) {
                if (aff.npe5__Organization__c == orgId) {
                    targetAff = aff;
                    break;
                }
            }

            // If the target org is already the primary affiliation → no-op
            if (targetAff != null && targetAff.npe5__Primary__c == true) {
                continue;
            }

            // Create the affiliation if it does not yet exist
            if (targetAff == null) {
                affiliationsToInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c      = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Status__c       = 'Current'
                ));
            }

            // Queue the contact for a primary-affiliation update.
            // NPSP's standard trigger/flow will:
            //   - promote the new affiliation to Primary + Current (clear EndDate)
            //   - demote the old primary to Former with EndDate = today
            contactsToUpdate.add(new Contact(
                Id                           = contactId,
                npsp__Primary_Affiliation__c = orgId
            ));
        }

        // DML 1: insert any new affiliation records
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }

        // DML 2: update contacts' primary affiliation lookup
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
