public class HouseholdService {

    /**
     * Creates a single NPSP household account and links every supplied contact to it.
     * The first contact in the list becomes the household's primary contact.
     *
     * @param members  New contacts (no Id, no AccountId). Must not be null or empty.
     * @return         The Id of the newly created household Account.
     * @throws IllegalArgumentException if members is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // Resolve the Household Account record type by developer name (no hard-coded Id)
        RecordType rt = [
            SELECT Id
            FROM RecordType
            WHERE SObjectType = 'Account'
              AND DeveloperName = 'HH_Account'
            LIMIT 1
        ];

        // Create the household.
        // In a real NPSP org the Name field is a formula on the Household RT and
        // auto-computes; we don't need to (and shouldn't) set it.
        // In environments where Name is a plain required text field (e.g. unit-test
        // sandboxes without the NPSP formula), we provide a minimal bootstrap value
        // so the insert succeeds; NPSP's naming trigger will overwrite it in prod.
        Account hh = new Account(RecordTypeId = rt.Id);

        if (!isNameFormula()) {
            hh.Name = members[0].LastName;
        }

        insert hh;

        // Link every contact to the household BEFORE insert so NPSP never
        // creates a separate (empty) household for any of them.
        for (Contact c : members) {
            c.AccountId = hh.Id;
        }
        insert members;

        // Designate the first contact as the primary contact.
        hh.npe01__One2OneContact__c = members[0].Id;
        update hh;

        return hh.Id;
    }

    /**
     * Returns true if Account.Name is a calculated (formula) field in this org.
     * When it is (i.e. NPSP is installed with the naming formula), the platform
     * auto-populates the value and we must NOT set it manually.
     */
    private static Boolean isNameFormula() {
        for (Schema.FieldDefinition fd : Schema.SObjectType.Account.getFields().values()) {
            if (fd.getName() == 'Name') {
                return fd.getDescribe().isCalculated();
            }
        }
        return false;
    }
}
