```apex
public with sharing class DiscountApprovalService {
    @AuraEnabled
    public static Boolean canApprove(Decimal discountPercent) {
        if (discountPercent == null || discountPercent < 0) {
            return false;
        }
        if (discountPercent <= 15) {
            return true;
        }
        return hasCustomPermission();
    }

    private static Boolean hasCustomPermission() {
        Id userId = UserInfo.getUserId();
        Set<Id> permSetIds = new Set<Id>();

        // Collect permission sets from direct assignments
        for (PermissionSetAssignment psa : [
            SELECT PermissionSetId FROM PermissionSetAssignment
            WHERE AssigneeId = :userId
        ]) {
            permSetIds.add(psa.PermissionSetId);
        }

        // Collect permission sets from permission set groups
        Set<Id> groupIds = new Set<Id>();
        for (PermissionSetGroupMembership psm : [
            SELECT PermissionSetGroupId FROM PermissionSetGroupMembership
            WHERE AssigneeId = :userId
        ]) {
            groupIds.add(psm.PermissionSetGroupId);
        }

        if (!groupIds.isEmpty()) {
            for (PermissionSet ps : [
                SELECT Id FROM PermissionSet
                WHERE Id IN (
                    SELECT PermissionSetId FROM PermissionSetGroupComponent
                    WHERE PermissionSetGroupId IN :groupIds
                )
            ]) {
                permSetIds.add(ps.Id);
            }
        }

        if (permSetIds.isEmpty()) {
            return false;
        }

        // Check whether any of the user's effective permission sets grant the custom permission
        Integer grantedCount = [
            SELECT COUNT() FROM PermissionSet
            WHERE Id IN :permSetIds AND Approve_Large_Discount__c = true
        ];

        return grantedCount > 0;
    }
}
